                int xx=x+step,zz=z+step;float d=distance[i];
                if(xx>=0&&xx<n)d=Math.min(d,distance[z*n+xx]+1);
                if(zz>=0&&zz<n){d=Math.min(d,distance[zz*n+x]+1);if(x>0)d=Math.min(d,distance[zz*n+x-1]+1.4142136f);if(x<n-1)d=Math.min(d,distance[zz*n+x+1]+1.4142136f);}
